package com.example.starter.calibration.domain;

import java.time.Instant;

/**
 * 标定参数版本实体（calibration_param 表对应对象）。
 */
public class CalibrationParam {

    private Long id;
    /** 全局唯一参数键，例如 cam_front.intrinsic */
    private String paramKey;
    private CalibrationKind kind;
    private SensorType sensorType;
    /** 版本号，同一参数键下唯一 */
    private String version;
    /** 参数内容（JSON 字符串） */
    private String contentJson;
    /** 内容摘要（SHA-256，hex） */
    private String contentDigest;
    private ParamStatus status;
    /** 生效起始时间（UTC，含），null 表示不限制 */
    private Instant effectiveFrom;
    /** 生效结束时间（UTC，不含），null 表示不限制 */
    private Instant effectiveTo;
    /** 适用车辆集合，存储为 JSON 数组字符串；null/空表示全部车辆 */
    private String vehicleScopeJson;
    /** 适用传感器集合，存储为 JSON 数组字符串；null/空表示该键对应传感器 */
    private String sensorScopeJson;
    /** 适用地图版本下界（含），null 表示不限制 */
    private String mapVersionMin;
    /** 适用地图版本上界（含），null 表示不限制 */
    private String mapVersionMax;

    private String createdBy;
    private Instant createdAt;
    private String approvedBy;
    private Instant approvedAt;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getParamKey() { return paramKey; }
    public void setParamKey(String paramKey) { this.paramKey = paramKey; }
    public CalibrationKind getKind() { return kind; }
    public void setKind(CalibrationKind kind) { this.kind = kind; }
    public SensorType getSensorType() { return sensorType; }
    public void setSensorType(SensorType sensorType) { this.sensorType = sensorType; }
    public String getVersion() { return version; }
    public void setVersion(String version) { this.version = version; }
    public String getContentJson() { return contentJson; }
    public void setContentJson(String contentJson) { this.contentJson = contentJson; }
    public String getContentDigest() { return contentDigest; }
    public void setContentDigest(String contentDigest) { this.contentDigest = contentDigest; }
    public ParamStatus getStatus() { return status; }
    public void setStatus(ParamStatus status) { this.status = status; }
    public Instant getEffectiveFrom() { return effectiveFrom; }
    public void setEffectiveFrom(Instant effectiveFrom) { this.effectiveFrom = effectiveFrom; }
    public Instant getEffectiveTo() { return effectiveTo; }
    public void setEffectiveTo(Instant effectiveTo) { this.effectiveTo = effectiveTo; }
    public String getVehicleScopeJson() { return vehicleScopeJson; }
    public void setVehicleScopeJson(String vehicleScopeJson) { this.vehicleScopeJson = vehicleScopeJson; }
    public String getSensorScopeJson() { return sensorScopeJson; }
    public void setSensorScopeJson(String sensorScopeJson) { this.sensorScopeJson = sensorScopeJson; }
    public String getMapVersionMin() { return mapVersionMin; }
    public void setMapVersionMin(String mapVersionMin) { this.mapVersionMin = mapVersionMin; }
    public String getMapVersionMax() { return mapVersionMax; }
    public void setMapVersionMax(String mapVersionMax) { this.mapVersionMax = mapVersionMax; }
    public String getCreatedBy() { return createdBy; }
    public void setCreatedBy(String createdBy) { this.createdBy = createdBy; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public String getApprovedBy() { return approvedBy; }
    public void setApprovedBy(String approvedBy) { this.approvedBy = approvedBy; }
    public Instant getApprovedAt() { return approvedAt; }
    public void setApprovedAt(Instant approvedAt) { this.approvedAt = approvedAt; }
}

package com.example.starter.calibration.domain;

import java.time.Instant;

/**
 * 灰度发布单：一次灰度发布显式指定车辆集合，对应一个新版本参数。
 */
public class CanaryRelease {

    private Long id;
    /** 发布单号，例如 REL-20260923-000001 */
    private String releaseId;
    private Long paramId;
    private String paramKey;
    private String newVersion;
    /** 参与灰度的车辆集合 JSON */
    private String vehiclesJson;
    private ReleaseStatus status;
    private String createdBy;
    private Instant createdAt;
    private String finishedBy;
    private Instant finishedAt;
    private String remark;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getReleaseId() { return releaseId; }
    public void setReleaseId(String releaseId) { this.releaseId = releaseId; }
    public Long getParamId() { return paramId; }
    public void setParamId(Long paramId) { this.paramId = paramId; }
    public String getParamKey() { return paramKey; }
    public void setParamKey(String paramKey) { this.paramKey = paramKey; }
    public String getNewVersion() { return newVersion; }
    public void setNewVersion(String newVersion) { this.newVersion = newVersion; }
    public String getVehiclesJson() { return vehiclesJson; }
    public void setVehiclesJson(String vehiclesJson) { this.vehiclesJson = vehiclesJson; }
    public ReleaseStatus getStatus() { return status; }
    public void setStatus(ReleaseStatus status) { this.status = status; }
    public String getCreatedBy() { return createdBy; }
    public void setCreatedBy(String createdBy) { this.createdBy = createdBy; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public String getFinishedBy() { return finishedBy; }
    public void setFinishedBy(String finishedBy) { this.finishedBy = finishedBy; }
    public Instant getFinishedAt() { return finishedAt; }
    public void setFinishedAt(Instant finishedAt) { this.finishedAt = finishedAt; }
    public String getRemark() { return remark; }
    public void setRemark(String remark) { this.remark = remark; }
}

package com.example.starter.calibration.domain;

import java.time.Instant;

/**
 * 灰度车辆明细：记录每辆灰度车辆发布前解析到的版本，回滚时恢复到该版本。
 */
public class CanaryVehicle {

    private Long id;
    private Long releaseId;
    private String vehicleId;
    /** 发布前该车辆解析到的参数版本 ID；null 表示此前无有效版本 */
    private Long previousParamId;
    private String previousVersion;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public Long getReleaseId() { return releaseId; }
    public void setReleaseId(Long releaseId) { this.releaseId = releaseId; }
    public String getVehicleId() { return vehicleId; }
    public void setVehicleId(String vehicleId) { this.vehicleId = vehicleId; }
    public Long getPreviousParamId() { return previousParamId; }
    public void setPreviousParamId(Long previousParamId) { this.previousParamId = previousParamId; }
    public String getPreviousVersion() { return previousVersion; }
    public void setPreviousVersion(String previousVersion) { this.previousVersion = previousVersion; }
}

package com.example.starter.calibration.domain;

import java.time.Instant;

/**
 * 参数解析历史（resolution 追踪记录）。
 * 每次解析命中参数版本后写入一条不可变记录，resolutionId 可追溯当时使用的版本；
 * 后续发布/回滚不修改本表，从而保证历史引用不变。
 */
public class ResolutionRecord {

    private Long id;
    /** 解析追踪 ID（UUID），对外可查询 */
    private String resolutionId;
    private String paramKey;
    private String vehicleId;
    private String sensorId;
    private String mapVersion;
    private Instant resolveTime;
    /** 当时命中的参数版本 ID */
    private Long resolvedParamId;
    private String resolvedVersion;
    private String contentDigest;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getResolutionId() { return resolutionId; }
    public void setResolutionId(String resolutionId) { this.resolutionId = resolutionId; }
    public String getParamKey() { return paramKey; }
    public void setParamKey(String paramKey) { this.paramKey = paramKey; }
    public String getVehicleId() { return vehicleId; }
    public void setVehicleId(String vehicleId) { this.vehicleId = vehicleId; }
    public String getSensorId() { return sensorId; }
    public void setSensorId(String sensorId) { this.sensorId = sensorId; }
    public String getMapVersion() { return mapVersion; }
    public void setMapVersion(String mapVersion) { this.mapVersion = mapVersion; }
    public Instant getResolveTime() { return resolveTime; }
    public void setResolveTime(Instant resolveTime) { this.resolveTime = resolveTime; }
    public Long getResolvedParamId() { return resolvedParamId; }
    public void setResolvedParamId(Long resolvedParamId) { this.resolvedParamId = resolvedParamId; }
    public String getResolvedVersion() { return resolvedVersion; }
    public void setResolvedVersion(String resolvedVersion) { this.resolvedVersion = resolvedVersion; }
    public String getContentDigest() { return contentDigest; }
    public void setContentDigest(String contentDigest) { this.contentDigest = contentDigest; }
}

