                VEHICLE_MAPPER, releaseId);
    }

    public int updateReleaseStatus(Long id, ReleaseStatus status, String finishedBy, Instant finishedAt) {
        return jdbc.update(
                "UPDATE canary_release SET status = ?, finished_by = ?, finished_at = ? WHERE id = ?",
