private boolean timeRangesOverlap(Instant fromA, Instant toA, Instant fromB, Instant toB) {
    Instant start = fromA == null ? null
            : (fromB == null ? fromA : (fromA.isAfter(fromB) ? fromA : fromB));
    Instant end = toA == null ? null
            : (toB == null ? toA : (toA.isBefore(toB) ? toA : toB));
    if (start == null || end == null) {
        return true;
    }
    return start.isBefore(end);
}

input.new_string:
private boolean timeRangesOverlap(Instant fromA, Instant toA, Instant fromB, Instant toB) {
    // null 下界视为负无穷，null 上界视为正无穷
    Instant start;
    if (fromA == null) {
        start = fromB;
    } else if (fromB == null) {
        start = fromA;
    } else {
        start = fromA.isAfter(fromB) ? fromA : fromB;
    }
    Instant end;
    if (toA == null) {
        end = toB;
    } else if (toB == null) {
        end = toA;
    } else {
        end = toA.isBefore(toB) ? toA : toB;
    }
    if (start == null || end == null) {
        return true;
    }
    return start.isBefore(end);
}

